function esc(v){return String(v==null?'':v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
function low(v){return String(v??'').trim().toLocaleLowerCase('nl-NL');}
function normalize(v){return low(v).normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[^a-z0-9]+/g,' ' ).trim();}
function short(v,n=160){const s=String(v??'').replace(/\s+/g,' ').trim();return s.length>n?s.slice(0,n-1)+'\u2026':s;}
function num(v){return Number(v)||0;}
function attr(xml,name){const m=xml.match(new RegExp('(?:^|\\s)'+name.replace(':','\\:')+'="([^"]*)"'));return m?xdecode(m[1]):'';}
function xdecode(s){return String(s??'').replace(/&(#x[0-9a-fA-F]+|#[0-9]+|amp|lt|gt|quot|apos);/g,(full,k)=>k==='amp'?'&':k==='lt'?'<':k==='gt'?'>':k==='quot'?'"':k==='apos'?"'":k.startsWith('#x')?String.fromCodePoint(parseInt(k.slice(2),16)):String.fromCodePoint(parseInt(k.slice(1),10)));}
function get(obj,keys){for(const key of keys){const v=obj[key];if(v!==undefined&&v!==null&&String(v).trim()!=='')return String(v).trim();}return '';}
function nval(row,aliases){const ent=Object.entries(row);for(const a of aliases){const key=normalize(a);const found=ent.find(([k,v])=>normalize(k)===key && v!==''&&v!=null);if(found)return String(found[1]).trim();}return '';}
function cellRowToObject(headers,values){let row={};headers.forEach((x,i)=>{const name=String(x??'').trim();if(name)row[name]=values[i]??'';});return row;}
function findHeader(rows){let best=-1,score=0;const words=['id','naam','toepassing','applicatie','ai functie','lesfase','omschrijving boeking','display name','naam toepassing','app id','application id','wat controleren','beheer via','groep','bronnen','beoordeling','application client id'];for(let i=0;i<Math.min(20,rows.length);i++){let a=rows[i]||[];let v=a.reduce((n,x)=>n+(words.some(k=>normalize(x)===k)?2:0)+(String(x).length>1?0.03:0),0);if(v>score){score=v;best=i;}}return score>2.1?best:0;}
function parseCsv(text){let first=String(text??'').replace(/^\ufeff/,'');let sample=first.slice(0,5000).split(/\r?\n/).slice(0,4).join('\n');const counts=[',',';','\t'].map(c=>[c,(sample.match(new RegExp(c==='\t'?'\\t':c===';'?';':',','g'))||[]).length]);counts.sort((a,b)=>b[1]-a[1]);const sep=counts[0][0];let rows=[],cur=[],field='',inQuote=false;for(let i=0;i<first.length;i++){const c=first[i];if(inQuote){if(c==='"'&&first[i+1]==='"'){field+='"';i++;}else if(c==='"')inQuote=false;else field+=c;}else if(c==='"')inQuote=true;else if(c===sep){cur.push(field);field='';}else if(c==='\n'){cur.push(field.replace(/\r$/,''));field='';if(cur.some(x=>x!==''))rows.push(cur);cur=[];}else field+=c;}cur.push(field.replace(/\r$/,''));if(cur.some(x=>x!==''))rows.push(cur);return rows;}
function rowsToObjects(rows){if(!rows||!rows.length)return [];const hi=findHeader(rows),head=rows[hi];return rows.slice(hi+1).filter(r=>r.some(x=>x!==null&&x!==undefined&&String(x).trim()!=='')).map(r=>cellRowToObject(head,r));}
function readUint32(buf,offset){return (buf[offset]|buf[offset+1]<<8|buf[offset+2]<<16|buf[offset+3]<<24)>>>0;}
function readUint16(buf,offset){return buf[offset]|buf[offset+1]<<8;}
function zipDirectory(buffer){const b=new Uint8Array(buffer),size=b.length;let end=-1;for(let i=size-22;i>=Math.max(0,size-65558);i--){if(readUint32(b,i)===0x06054b50){end=i;break;}}if(end<0)throw Error('Geen herkenbaar ZIP/XLSX-bestand.');const count=readUint16(b,end+10),offset=readUint32(b,end+16);if(count>25000)throw Error('Te veel onderdelen in het bestand.');let i=offset,out=new Map();for(let n=0;n<count;n++){if(readUint32(b,i)!==0x02014b50)throw Error('ZIP-index kan niet worden gelezen.');let method=readUint16(b,i+10),compressed=readUint32(b,i+20),uncompressed=readUint32(b,i+24),len=readUint16(b,i+28),extra=readUint16(b,i+30),comment=readUint16(b,i+32),start=readUint32(b,i+42),name=new TextDecoder().decode(b.slice(i+46,i+46+len));if(uncompressed>85000000)throw Error('Een bestandsonderdeel is te groot voor lokale controle.');out.set(name,{method,compressed,uncompressed,start});i+=46+len+extra+comment;}return {bytes:b,entries:out};}
async function zipPart(zip,name){let entry=zip.entries.get(name);if(!entry)return null;const b=zip.bytes,off=entry.start;if(readUint32(b,off)!==0x04034b50)throw Error('ZIP-onderdeel heeft een ongeldige start.');const dataStart=off+30+readUint16(b,off+26)+readUint16(b,off+28);const compressed=b.slice(dataStart,dataStart+entry.compressed);let output=compressed;if(entry.method===8){if(typeof DecompressionStream==='undefined')throw Error('Deze browser kan gecomprimeerde Excelbestanden niet lezen. Gebruik recente Chrome, Edge of Safari.');const stream=new Blob([compressed]).stream().pipeThrough(new DecompressionStream('deflate-raw'));output=new Uint8Array(await new Response(stream).arrayBuffer());}else if(entry.method!==0)throw Error('Deze ZIP-compressie wordt niet ondersteund.');if(output.length>90000000)throw Error('Een bestandsonderdeel is groter dan toegestaan.');return new TextDecoder().decode(output);}
async function extractXlsx(arrayBuffer){const zip=zipDirectory(arrayBuffer),book=await zipPart(zip,'xl/workbook.xml'),rels=await zipPart(zip,'xl/_rels/workbook.xml.rels');if(!book||!rels)throw Error('Geen geldig XLSX-document.');let map=new Map();for(const m of rels.matchAll(/<Relationship\b([^>]+)\/?\s*>/g)){const id=attr(m[1],'Id'),target=attr(m[1],'Target');const path=target.startsWith('/')?target.slice(1):'xl/'+target.replace(/^\.\//,'');if(id)map.set(id,path.replace(/\/[^/]+\/\.\.\//g,'/'));}let shared=[];const strings=await zipPart(zip,'xl/sharedStrings.xml');if(strings){for(const m of strings.matchAll(/<si(?:\s[^>]*)?>([\s\S]*?)<\/si>/g)){let parts=[];for(const t of m[1].matchAll(/<t(?:\s[^>]*)?>([\s\S]*?)<\/t>/g))parts.push(xdecode(t[1]));shared.push(parts.join(''));if(shared.length>450000)throw Error('Te veel gedeelde tekstwaarden.');}}let sheets=[];for(const m of book.matchAll(/<sheet\b([^>]*)\/?\s*>/g)){const name=attr(m[1],'name'),id=attr(m[1],'r:id'),path=map.get(id);if(path&&name){sheets.push({name,path});}}let data=[];for(const sheet of sheets){if(/grafiekdata|keuzelijsten|rekenblad|dashboard|start|begrippen|m365.inrichting/i.test(sheet.name))continue;const xml=await zipPart(zip,sheet.path);if(!xml)continue;const rows=[];let n=0;for(const rm of xml.matchAll(/<row\b[^>]*>([\s\S]*?)<\/row>/g)){const row=[],cells=rm[1];for(const cm of cells.matchAll(/<c\b([^>]*?)(?:\/\s*>|>([\s\S]*?)<\/c>)/g)){const ref=attr(cm[1],'r');if(!ref)continue;const letters=(ref.match(/^[A-Z]+/)||[])[0];if(!letters)continue;let col=0;for(const ch of letters)col=col*26+ch.charCodeAt(0)-64;col--;if(col>150)continue;const t=attr(cm[1],'t');let body=cm[2]||'',v=(body.match(/<v(?:\s[^>]*)?>([\s\S]*?)<\/v>/)||[])[1]??'';if(t==='inlineStr'){v=[...body.matchAll(/<t(?:\s[^>]*)?>([\s\S]*?)<\/t>/g)].map(x=>xdecode(x[1])).join('');}else if(t==='s'){v=shared[Number(v)]??'';}else v=xdecode(v);row[col]=v;}if(row.some(x=>x!==undefined&&x!==''))rows.push(row);if(++n>120000)throw Error('Te veel rijen; splits de export op.');}if(rows.length)data.push({sheet:sheet.name,rows});}return data;}
async function extractDocx(arrayBuffer){const zip=zipDirectory(arrayBuffer),xml=await zipPart(zip,'word/document.xml');if(!xml)throw Error('Wordbestand kon niet worden gelezen.');let paras=[];for(const p of xml.matchAll(/<w:p\b[^>]*>([\s\S]*?)<\/w:p>/g)){const lines=[...p[1].matchAll(/<w:t(?:\s[^>]*)?>([\s\S]*?)<\/w:t>/g)].map(t=>xdecode(t[1]));if(lines.length)paras.push(lines.join(''));}return paras.join('\n').slice(0,100000);}
const keys={id:['ID','Nr','Nummer','Applicatie-ID','App ID','AI-ID','Bron-ID'],name:['Naam','Toepassing','Toepassing / dienst','Applicatie','Product / toepassing','Systeem','Product','Display name','displayName'],description:['Beschrijving','Waarvoor','Omschrijving','Doel','Concrete AI-handeling','Wat AI doet'],area:['Gebruiksgebied','Domein','Schoolproces','Proces','Afdeling'],layer:['Technische laag','Soort','Type','Categorie'],parent:['Valt onder','Bovenliggende toepassing','Platform','Hoofdproduct']};
function classify(filename,sheet,rows){const title=normalize(filename+' '+sheet);if(/financiele mutaties|kostenboekingen|boekingen|grootboek|ict uitgave/.test(title))return 'financieel';if(/(^| )entra( |$)|serviceprincipal|service principal|enterprise application/.test(normalize(sheet))||/entra export|serviceprincipal/.test(title))return 'entra';if(/ai functies|ai register|volledige ai|ai bron/.test(title))return 'ai';if(/rollen telling|beheerrollen|roltoewijzingen|roles export/.test(title))return 'rollen';if(/dpia registraties/.test(title))return 'dpia';if(/ai beheerbron/.test(title))return 'ai-beheer';if(/iam documenten|m365 inrichting|autorisatie/.test(title))return 'beleid';if(/controle|onderzoek|te controleren|open punt/.test(title))return 'controles';if(/onderdelen/.test(normalize(sheet)))return 'onderdelen';if(/apparaten|hardware/.test(normalize(sheet)))return 'apparaten';const sample=rows[0]||{};const cols=Object.keys(sample).map(normalize);const has=(needle)=>cols.some(x=>x===normalize(needle));if(has('Omschrijving boeking')||has('Saldo')&&has('Rekeningnummer'))return 'financieel';if(has('AI-ID')||has('Wat AI doet')&&has('Lesfase'))return 'ai';if(has('ServicePrincipalId')||has('Application (client) ID')||has('ApplicationId')&&has('DisplayName')||has('Zichtbaarheid')&&has('Enabled in export'))return 'entra';if(has('Wat controleren')||has('Prioriteit')&&has('Status')&&has('Onderwerp'))return 'controles';if(has('Groep')&&has('Beheer via'))return 'apparaten';if(has('Document')&&has('Status')&&has('Doel'))return 'beleid';if(has('Naam')&&(has('Soort')||has('Gebruiksgebied')||has('Technische laag'))||has('Toepassing / dienst'))return 'toepassingen';if(has('Naam')&&has('Valt onder')&&has('Type'))return 'onderdelen';return 'onbekend';}
function addMerged(map,key,item){const old=map.get(key);if(!old){map.set(key,item);return;}const newer=Object.assign({},old);for(const [k,v] of Object.entries(item)){if(v==null||v==='')continue;const a=String(newer[k]??'').trim();if(!a||a==='?'||a.toLowerCase()==='onbekend'||(v.length>a.length&&['description','action','input','teacher','student','didactics','local','sources','parent','purpose','kind'].includes(k)))newer[k]=v;}newer.sources=[...new Set([...(old.sources||[]),...(item.sources||[])])];map.set(key,newer);}
function financeSignal(desc){const s=String(desc||'');if(!s||s.length>450)return '';if(!/(licen|licent|software|saas|hosting|cloud|ict|it.?dienst|office|microsoft|jamf|magister|toets|leerling|edu|applicati|programma|sharepoint|teams|nivo|inloggen|abonnement|onderhoud.+(systeem|server|applicati))\b/i.test(s))return '';let part=s.split(/\s[-\u2013]\s/)[0].replace(/\b(?:factuur|licentie|licenties|onderhoud|software|202[0-9])\b/gi,'').trim();if(part.length<3||part.length>110)return '';return part;}
