  const item={id:id||'AI-?',name:name||'AI-functie',product:nval(row,['Product','Toepassing','Bovenliggende toepassing']),parent:nval(row,['Bovenliggende toepassing','Valt onder']),phase:nval(row,['Lesfase','Fase']),action:nval(row,['Concrete AI-handeling','Wat AI doet','Beschrijving']),input:nval(row,['Docent / medewerker stelt in','Invoer','Docent stelt in']),teacher:nval(row,['Docent / medewerker controleert','Docent controleert','Wie beoordeelt']),student:nval(row,['Leerling doet','Leerlinghandeling']),users:nval(row,['Wie gebruikt AI','Gebruikers']),didactics:nval(row,['Didactische onderbouwing','Didactische aandachtspunten']),steer:nval(row,['Stuurbaarheid','Instelbaarheid']),local:nval(row,['Gebruik bij school','Schoolstatus','Lokale status']),aiAct:nval(row,['AI Act indicatie','AI Act','AI Act classificatie']),sources:[source]};addMerged(state.ai,key,item);newCount++;
