function exportJson(){const result={schema:'eai-school-ict-v1',created:new Date().toISOString(),apps:array(state.apps),ai:array(state.ai),connections:array(state.connections),checks:allFindings(),signals:state.derived,parts:array(state.parts),dpia:array(state.dpia),aiControls:array(state.aiControls),devices:array(state.devices),sources:state.sources.map(x=>({name:x.kind==='financieel'?'ICT-registratie 2026':x.name,kind:x.kind,rows:x.rows}))};download('Emmauscollege_ICT_nulmeting.json',new Blob([JSON.stringify(result,null,2)],{type:'application/json'}));toast('JSON-bestand gedownload.');}
function printTable(title,headers,rows,limit=100){let out='<h2>'+esc(title)+'</h2><table><thead><tr>'+headers.map(h=>'<th>'+esc(h)+'</th>').join('')+'</tr></thead><tbody>'+rows.slice(0,limit).map(r=>'<tr>'+r.map(x=>'<td>'+esc(short(x,260))+'</td>').join('')+'</tr>').join('')+'</tbody></table>';if(rows.length>limit)out+='<p>Een deel van de registraties staat uitsluitend in de volledige Excel-export ('+rows.length+' totaal).</p>';return out;}
function exportPdf(){const apps=array(state.apps),ent=array(state.connections),ai=array(state.ai),checks=allFindings();const date=new Date().toLocaleDateString('nl-NL');$('printReport').innerHTML='<h1>Emmauscollege | Digitale omgeving</h1><p>Inventarisatie op basis van in deze sessie ingelezen bronnen. '+esc(date)+'. Actueel gebruik en inrichting vragen waar vermeld om bevestiging.</p><div class="print-summary"><span><strong>'+apps.length+'</strong> toepassingen en diensten</span><span><strong>'+ent.length+'</strong> Entra-koppelingen</span><span><strong>'+ai.length+'</strong> AI-functies</span><span><strong>'+checks.length+'</strong> controlepunten</span></div>'+printTable('Toepassingen',['ID','Naam','Soort','Gebruik op school'],apps.map(x=>[x.id,x.name,x.kind,x.local]),100)+'<div class="pagebreak"></div>'+printTable('Entra-koppelingen',['ID','Naam','Status export'],ent.map(x=>[x.id,x.name,x.enabled]),100)+'<div class="pagebreak"></div>'+printTable('AI-functies',['ID','Functie','Product','Lesfase'],ai.map(x=>[x.id,x.name,x.product,x.phase]),110)+'<div class="pagebreak"></div>'+printTable('Controlepunten',['Onderwerp','Controle','Toelichting'],checks.map(x=>[x.category,x.name,x.explanation]),90)+'<h2>Bronnen</h2><p>'+state.sources.map(x=>esc(x.kind==='financieel'?'ICT-registratie 2026':x.name)).join('; ')+'</p><p>Een open controle is niet hetzelfde als een geconstateerde tekortkoming. Entra-registraties bewijzen geen actieve gegevensuitwisseling.</p>';
 window.print();}
function installEvents(){const showGate=()=>{$('gate').hidden=false;$('gateInput').focus();};$('unlockFour').addEventListener('click',showGate);$('gateCancel').addEventListener('click',()=>{$('gate').hidden=true;$('gateError').hidden=true;$('unlockFour').focus();});$('gateForm').addEventListener('submit',e=>{e.preventDefault();if($('gateInput').value.trim()==='Emmauscollege'){$('gate').hidden=true;$('notFound').hidden=true;$('workspace').hidden=false;document.title='Emmauscollege | ICT-scan';renderAll();}else{$('gateError').hidden=false;$('gateInput').select();}});document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!$('gate').hidden){$('gateCancel').click();}});
 const choose=()=>$('fileInput').click();for(const id of ['topImport','emptyImport','sourcesImport'])$(id).addEventListener('click',choose);$('fileInput').addEventListener('change',async e=>{const files=Array.from(e.target.files||[]);e.target.value='';await handleFiles(files);});for(const el of document.querySelectorAll('[data-view]'))el.addEventListener('click',()=>selectView(el.dataset.view));for(const el of document.querySelectorAll('[data-open]'))el.addEventListener('click',()=>selectView(el.dataset.open));for(const id of ['appsSearch','connectionsSearch','aiSearch','findingsSearch'])$(id).addEventListener('input',()=>({appsSearch:renderApps,connectionsSearch:renderConnections,aiSearch:renderAiList,findingsSearch:renderFindings}[id])());$('modeRegistered').addEventListener('click',()=>{state.findingMode='registered';$('findingsFilter').value='';renderFindings();});$('modeSignals').addEventListener('click',()=>{state.findingMode='signals';$('findingsFilter').value='';renderFindings();});for(const id of ['appsArea','appsType'])$(id).addEventListener('change',()=>{state.area=$('appsArea').value;state.type=$('appsType').value;renderApps();});$('findingsFilter').addEventListener('change',renderFindings);
 $('topPdf').addEventListener('click',exportPdf);$('exportPdf').addEventListener('click',exportPdf);$('exportExcel').addEventListener('click',exportWorkbook);$('exportJson').addEventListener('click',exportJson);const zone=$('dropzone');for(const event of ['dragenter','dragover'])zone.addEventListener(event,e=>{e.preventDefault();zone.classList.add('dragging');});for(const event of ['dragleave','drop'])zone.addEventListener(event,e=>{e.preventDefault();zone.classList.remove('dragging');});zone.addEventListener('drop',async e=>{await handleFiles(Array.from(e.dataTransfer?.files||[]));});}
$('reportDate').textContent=new Date().toLocaleDateString('nl-NL',{day:'numeric',month:'long',year:'numeric'});installEvents();renderSources();